<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Session\Infrastructure\Driven;

use PDO;
use Override;
use DateInterval;
use DateTimeImmutable;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\SessionInfo;

/**
 * SQL-backed implementation of the SessionStoreGateway port using PDO.
 *
 * Persists OAuth authorization session records in the _oauth_session table, storing the
 * serialised user identity and MFA state as a JSON blob in the auth_data column. On
 * construction, expired sessions are purged proactively so that old rows do not accumulate.
 * All lookups filter by expiration to ensure stale sessions are never returned even if a
 * periodic cleanup has not yet run. The client IP address and User-Agent are recorded for
 * auditing purposes but are not used for any validation logic. Session rotation (via
 * updateSession) replaces the opaque state key while keeping all other session data intact,
 * preventing session fixation between authentication steps.
 */
class SessionStoreSqlAdapter implements SessionStoreGateway
{
    public function __construct(
        private readonly PDO $pdo
    ) {
        $this->clearTemp();
    }

    /**
     * Loads an active, unexpired session by its opaque state key.
     * Returns null when no matching record is found or when the session has expired.
     */
    #[Override]
    public function loadSession(string $state): ?SessionInfo
    {
        $now = new \DateTime();
        $stmt = $this->pdo->prepare('SELECT client_id, expiration, issuer, auth_data, csid FROM _oauth_session where session = :session and expiration > :now');
        $stmt->bindValue('session', $state, PDO::PARAM_STR);
        $stmt->bindValue('now', $now->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->execute();
        $result = null;
        if ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {
            $data = (array)json_decode($row['auth_data']);
            // $now = new \DateTime();
            // $until = new \DateTime($row['expiration']);
            $result = new SessionInfo(
                csid: $row['csid'],
                issuer: $row['issuer'],
                userId: $data['userId'],
                clientId: $row['client_id'],
                withMfa: $data['withMfa'],
            );
        }
        return $result;
    }

    /**
     * Finds the most recent unexpired session state key for the given cross-session identifier.
     * Returns null when no active session exists for the provided csid value.
     */
    #[Override]
    public function findActiveSessionIdByCsid(string $csid): ?string
    {
        $now = new \DateTime();
        $stmt = $this->pdo->prepare('SELECT session FROM _oauth_session WHERE csid = :csid AND expiration > :now ORDER BY expiration DESC LIMIT 1');
        $stmt->bindValue('csid', $csid, PDO::PARAM_STR);
        $stmt->bindValue('now', $now->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->execute();
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        return is_array($row) && isset($row['session']) ? (string) $row['session'] : null;
    }

    /**
     * Inserts a new session row associating the state key with the client, issuer, user identity, and MFA state.
     * The session expiration is calculated by adding the given interval to the current timestamp.
     */
    #[Override]
    public function saveSession(
        string $state,
        ClientData $clientDetails,
        string $issuer,
        ChallengesState $keypass,
        AuthenticationResult $validationData,
        string $csid,
        DateInterval $expiration
    ): void {
        $now = new DateTimeImmutable();

        $data = ['withMfa' => $keypass->withMfa, 'userId' => $validationData->id ];
        $expires = $now->add($expiration);

        $serverParams = $_SERVER;
        $ipAddress = $serverParams['REMOTE_ADDR'] ?? null;
        $userAgent = $serverParams['HTTP_USER_AGENT'] ?? null;

        $stmt = $this->pdo->prepare('INSERT INTO _oauth_session ' .
            '(session, expiration, client_id, issuer, auth_data, csid, ip_address, user_agent, last_used_at, client_name) VALUES ' .
            '(:state, :expiration, :client, :issuer, :data, :csid, :ip_address, :user_agent, :last_used_at, :client_name)');
        $stmt->bindValue('state', $state, PDO::PARAM_STR);
        $stmt->bindValue('expiration', $expires->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->bindValue('client', $clientDetails->id, PDO::PARAM_STR);
        $stmt->bindValue('issuer', $issuer, PDO::PARAM_STR);
        $stmt->bindValue('data', json_encode($data), PDO::PARAM_STR);
        $stmt->bindValue('csid', $csid, PDO::PARAM_STR);
        $stmt->bindValue('ip_address', $ipAddress, PDO::PARAM_STR);
        $stmt->bindValue('user_agent', $userAgent !== null ? substr($userAgent, 0, 500) : null, PDO::PARAM_STR);
        $stmt->bindValue('last_used_at', $now->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->bindValue('client_name', $clientDetails->id, PDO::PARAM_STR);
        $stmt->execute();
    }

    /**
     * Replaces the opaque state key for an existing session without altering any other column.
     * Used during mid-flow state rotation to prevent session fixation attacks.
     *
     * @return void
     */
    #[Override]
    public function updateSession(string $newState, string $oldState): void
    {
        $stmt = $this->pdo->prepare('UPDATE _oauth_session set session = :old, expiration = :new where session = :old');
        $stmt->bindValue('old', $newState, PDO::PARAM_STR);
        $stmt->bindValue('new', $oldState, PDO::PARAM_STR);
        $stmt->execute();
    }

    /**
     * Removes the session row identified by the given state key from the database.
     * Called on logout or after the authorization code has been successfully exchanged for tokens.
     *
     * @return void
     */
    #[Override]
    public function deleteSession(string $state): void
    {
        $stmt = $this->pdo->prepare('DELETE FROM _oauth_session where session = :session');
        $stmt->bindValue('session', $state, PDO::PARAM_STR);
        $stmt->execute();
    }

    /**
     * Deletes all expired session rows from the database.
     * Delegates to the internal clearTemp helper which is also called on construction.
     */
    #[Override]
    public function purgeExpired(): void
    {
        $this->clearTemp();
    }

    private function clearTemp(): void
    {
        $now = new \DateTimeImmutable();
        $stmt = $this->pdo->prepare('DELETE FROM _oauth_session where expiration < :expiration');
        $stmt->bindValue('expiration', $now->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->execute();
    }
}
